const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-mail-sync", node: "Code: Enqueue Attachment Jobs" } });
const redis = require('redis');
const path = require('path');

// PROJ-53 iteration 4: attachment classification/import no longer runs here.
// alice-mail-sync is on a minutely schedule and must never load the DMS model
// (GPU contention with the chat model). Instead it only enqueues one job per
// newly stored mail that has at least one attachment surviving the extension
// prefilter; alice-mail-attachment-processor drains the queue nightly at 02:00.
const ctx = $('Prepare Mailbox Data').first().json;
const prev = $input.first().json;
const storedEmails = prev.storedEmails || [];

const QUEUE_KEY = 'alice:mail:attachment_queue';

// Prefilter constants copied verbatim from the removed "Code: Import Attachments"
// node so the queue never fills with attachments the processor would reject anyway.
const SUPPORTED_EXTENSIONS = new Set([
  '.pdf','.txt','.md','.docx','.doc','.xlsx','.xls','.odt','.ods',
  '.jpg','.jpeg','.png','.webp','.heic','.tif','.tiff',
  // PROJ-53 iteration 2 additions (video)
  '.mp4','.mov','.avi','.mkv','.webm',
  // PROJ-53 iteration 2 additions (audio)
  '.mp3','.wav','.m4a','.ogg','.flac'
]);
const IMAGE_EXTENSIONS = new Set(['.jpg','.jpeg','.png','.webp','.heic','.tif','.tiff']);
const IMAGE_JUNK_MAX_BYTES = 20480;
const ATTACHMENT_MAX_BYTES = 52428800; // 50 MB

function prefilterAttachment(att) {
  const ext = path.extname(att.name || '').toLowerCase();
  if (!SUPPORTED_EXTENSIONS.has(ext)) return { keep: false, reason: 'unsupported_extension', ext };
  const size = Number(att.size_bytes || 0);
  if (size > ATTACHMENT_MAX_BYTES) return { keep: false, reason: 'too_large', ext, size };
  const isImage = IMAGE_EXTENSIONS.has(ext) || String(att.mime_type || '').startsWith('image/');
  if (isImage && size < IMAGE_JUNK_MAX_BYTES) return { keep: false, reason: 'image_junk', ext };
  return { keep: true, reason: null, ext };
}

let queued = 0, skippedNoCandidate = 0;
const jobs = [];

for (const mail of storedEmails) {
  const attachments = mail.attachments || [];
  if (attachments.length === 0) continue;
  // Only mails with at least one candidate are queued. The full attachment array
  // is carried along (with original indices) because the processor addresses
  // attachments by their IMAP attachment_index.
  const hasCandidate = attachments.some(att => prefilterAttachment(att).keep);
  if (!hasCandidate) {
    skippedNoCandidate++;
    continue;
  }
  jobs.push({
    queued_at: new Date().toISOString(),
    mailbox: {
      mailboxId: ctx.mailboxId,
      host: ctx.host,
      port: ctx.port,
      ssl: ctx.ssl,
      username: ctx.username,
      passwordEnc: ctx.passwordEnc
    },
    uid: mail.uid,
    message_id: mail.message_id || '',
    weaviate_uuid: mail.weaviate_uuid || null,
    subject: mail.subject || '',
    sender: mail.sender || '',
    date: mail.date || '',
    body_preview: mail.body_preview || '',
    attachments: attachments.map(a => ({ name: a.name, mime_type: a.mime_type, size_bytes: a.size_bytes }))
  });
}

if (jobs.length > 0) {
  let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
  const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
  await client.connect();
  try {
    for (const job of jobs) {
      try {
        await client.rPush(QUEUE_KEY, JSON.stringify(job));
        queued++;
      } catch(e) {
        logger.warn(`[PROJ-53] Enqueue failed (uid=${job.uid}): ${e.message}`);
      }
    }
  } finally {
    await client.quit();
  }
}

const enqueueStats = { queued, mails_without_candidate: skippedNoCandidate };
logger.info(`[PROJ-53] Attachment jobs enqueued for mailbox ${ctx.mailboxId}: ${JSON.stringify(enqueueStats)}`);

return [{ json: { ...prev, enqueueStats } }];

// PROJ-53: fan out the stored mails so the MQTT node fires once per inserted
// Email object (n8n runs a node once per input item). Mails without a Weaviate
// UUID are dropped - there would be nothing for the thumbnailer to attach to.
const prev = $input.first().json;
const stored = (prev.storedEmails || []).filter(m => m.weaviate_uuid);
if (stored.length === 0) {
  return [{ json: { _no_mqtt: true } }];
}
return stored.map(m => ({ json: { _no_mqtt: false, weaviate_uuid: m.weaviate_uuid, subject: m.subject } }));
